:host { font-family: "Inter Variable", sans-serif; font-size:16px; line-height:1.5; color:var(--foreground); } :focus-visible { outline:2px solid var(--ring); outline-offset:2px; } button,input { font:inherit; }
.ds-button { --button-fill: var(--primary);
		--button-ink: var(--primary-foreground);
		display: inline-flex;
		align-items: center;
		justify-content: center;
		min-width: 0;
		max-width: 100%;
		overflow-wrap: anywhere;
		gap: 0.5rem;
		min-height: 2.25rem;
		padding: 0.375rem 1rem;
		border: 1px solid var(--button-fill);
		border-radius: 0.5rem;
		background: var(--button-fill);
		color: var(--button-ink);
		font-size: 0.875rem;
		font-weight: 600;
		line-height: 1.25rem;
		text-align: center;
		text-decoration: none;
		cursor: pointer;
		transition: background-color 120ms ease, border-color 120ms ease; }
@media (hover: hover) { .ds-button:not(:disabled, [aria-disabled='true']):hover { --button-fill: var(--primary-hover); } }
.ds-button:disabled, .ds-button[aria-disabled='true'] { opacity: 0.5;
		cursor: not-allowed; }
@media (pointer: coarse) { .ds-button, .ds-input { min-height: 2.75rem; }
.ds-button { min-width: 2.75rem; } }
@media (prefers-reduced-motion: reduce) { .ds-button { transition: none; } }

